mapper.select:
/** login-log-mapper.getLoginLogListCountByParam (로그인 통계 목록 갯수) */ SELECT COUNT(*) FROM ( SELECT LL.LOGIN_LOG_ID, LL.LOGIN_TYPE, LL.LOGIN_ID, LL.SUCCESS_FLAG, LL.REMOTE_ADDR, LL.MEMO, DATE_FORMAT(LL.LOGIN_DATE, '%Y-%m-%d %H:%i:%s') AS LOGIN_DATE, R.AUTHORITY FROM OP_LOGIN_LOG LL LEFT OUTER JOIN OP_MANAGER M ON M.LOGIN_ID = LL.LOGIN_ID AND LL.LOGIN_TYPE = 'manager' LEFT OUTER JOIN OP_USER_ROLE R ON R.USER_ID = M.USER_ID AND R.AUTHORITY LIKE 'ROLE_ADMIN_%'
AND R.AUTHORITY = #{srcRole}
) A LEFT OUTER JOIN OP_ROLE R ON R.AUTHORITY = A.AUTHORITY

/* login-log-mapper.getLoginLogListByParam (로그인 통계 목록) */ SELECT B.login_log_id, B.login_type, B.login_id AS login_id, B.success_flag, B.remote_addr AS remote_addr, B.memo, B.login_date, B.authority, B.role_name FROM ( SELECT A.login_log_id, A.login_type, A.login_id, A.success_flag, A.remote_addr, A.memo, A.login_date, R.authority, R.role_name FROM (
SELECT LL.login_log_id, LL.login_type, LL.login_id, LL.success_flag, LL.remote_addr, LL.memo, DATE_FORMAT(LL.login_date, '%Y-%m-%d %H:%i:%s') AS login_date, R.authority FROM op_login_log LL LEFT OUTER JOIN op_manager M ON M.login_id = LL.login_id AND LL.login_type = 'manager' LEFT OUTER JOIN op_user_role R ON R.user_id = M.user_id AND R.authority LIKE 'ROLE_ADMIN_%'
AND R.authority = #{srcRole}
ORDER BY LL.login_date DESC
) A LEFT OUTER JOIN op_role R ON R.authority = A.authority )B

/* login-log-mapper.getUserLoginLogListByParam (사용자 로그인 로그 목록 조회) */ SELECT A.login_log_id, A.login_type, A.login_id AS login_id, A.success_flag, A.remote_addr AS remote_addr, A.memo, A.login_date FROM (
SELECT LL.login_log_id, LL.login_type, LL.login_id, LL.success_flag, LL.remote_addr, LL.memo, DATE_FORMAT(LL.login_date, '%Y-%m-%d %H:%i:%s') AS login_date FROM op_user_login_log LL
ORDER BY LL.login_log_id DESC
) A

select
	case when (
		(
			select auth_num from OP_MANAGER_LOGIN_EMAIL
			where login_id = #{loginId}
			and created_at > date_sub(sysdatetime, interval 5 minute)
			order by created_at desc
			limit 1
			) = #{authNum}
		) > 0
	then 1
	else 0
end as CHK
